scripts/build-static.mjs:
import { cp, mkdir, rm } from "node:fs/promises";
import { resolve } from "node:path";

const root=process.cwd();
const dist=resolve(root,"dist");
await rm(dist,{recursive:true,force:true});
await mkdir(dist,{recursive:true});
await cp(resolve(root,"index.html"),resolve(dist,"index.html"));
await cp(resolve(root,"src"),resolve(dist,"src"),{recursive:true});
await cp(resolve(root,"styles"),resolve(dist,"styles"),{recursive:true});
console.log("Built application shell into dist/");

scripts/prepare-media.mjs:
import sharp from "sharp";
import { mkdir } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { MEDIA } from "./media-manifest.mjs";

const root=process.cwd();
const targetRoot=resolve(root,"dist","assets","lume");

async function download(url){
  const response=await fetch(url,{headers:{"user-agent":"VIIVERSION-LUME-Build/1.0","accept":"image/avif,image/webp,image/*,*/*"}});
  if(!response.ok) throw new Error(`Failed media download ${response.status}: ${url}`);
  return Buffer.from(await response.arrayBuffer());
}

for(const [name,item] of Object.entries(MEDIA)){
  const output=resolve(targetRoot,item.output);
  await mkdir(dirname(output),{recursive:true});
  const input=await download(item.source);
  let pipeline=sharp(input).rotate();
  if(name==="logo") pipeline=pipeline.trim({background:{r:0,g:0,b:0,alpha:0}}).resize({width:item.width,withoutEnlargement:false,kernel:"lanczos3"});
  else pipeline=pipeline.resize({width:item.width,withoutEnlargement:true,kernel:"lanczos3"});
  if(item.lossless) pipeline=pipeline.webp({lossless:true,effort:6});
  else pipeline=pipeline.webp({quality:82,effort:5,smartSubsample:true});
  await pipeline.toFile(output);
  console.log(`Prepared ${item.output}`);
}

