const navIcons = {home:"home",menu:"menu",guest:"guest",reserve:"reserve",concierge:"ask"};
const ROUTABLE_TABS = new Set(["home","menu","guest","reserve","concierge"]);
let lastTab=null;

function routeFor(tab){ return "#/"+tab; }
function tabFromHash(){
  const match=/^#\/(home|menu|guest|reserve|concierge)$/.exec(location.hash);
  return match?.[1] || "home";
}
function navigate(tab,{replace=false}={}){
  const next=ROUTABLE_TABS.has(tab)?tab:"home";
  const changed=store.get().tab!==next;
  if(changed) store.set({tab:next});
  const hash=routeFor(next);
  if(location.hash!==hash){
    if(replace) history.replaceState(null,"",hash);
    else history.pushState(null,"",hash);
  }
  if(!changed) render();
}

function i18nFor(state){
  return {
    t:(path)=>translate(state.lang,path),
    tr:(value)=>localize(state.lang,value)
  };
}

function renderTopbar(state){
  topbar.innerHTML = [
    '<a class="brand-lockup" href="#/home" data-action="tab" data-tab="home" aria-label="LUME home"><img class="brand-logo" src="'+BRAND.logo+'" alt="'+escapeHtml(BRAND.fullName)+'"></a>',
    '<div class="langs">'+SUPPORTED_LANGS.map(lang=>'<button type="button" class="'+(state.lang===lang?"active":"")+'" data-action="lang" data-lang="'+lang+'">'+lang.toUpperCase()+'</button>').join("")+'</div>'
  ].join("");
}

function renderNav(state){
  const t=(path)=>translate(state.lang,path);
  const items=[["home","home"],["menu","menu"],["guest","guest"],["reserve","reserve"],["concierge","ask"]];
  nav.innerHTML=items.map(([tab,key])=>[
    '<a class="nav-btn '+(state.tab===tab?"active":"")+'" href="'+routeFor(tab)+'" data-action="tab" data-tab="'+tab+'">',
    '<span class="nav-icon">'+icon(navIcons[tab],{size:20})+'</span><span>'+escapeHtml(t("nav."+key))+'</span></a>'
  ].join("")).join("");
}

function render(){
  const state=store.get();
  const tabChanged=state.tab!==lastTab;
  document.documentElement.lang=state.lang;
  renderTopbar(state);
  renderNav(state);
  const renderer=renderers[state.tab]||renderHome;
  screen.innerHTML=renderer(state,i18nFor(state));
  if(tabChanged) screen.scrollTop=0;
  lastTab=state.tab;
}

function updateDraftFromDom(){
  const fields=[...document.querySelectorAll("[data-field]")];
  if(!fields.length) return;
  const draft={...store.get().reservationDraft};
  fields.forEach(field=>{
    const key=field.dataset.field;
    draft[key]=key==="guests"?Number(field.value||0):field.value;
  });
  store.set({reservationDraft:draft});
}

function promptForSpace(space,lang){
  const title=localize(lang,space.title);
  if(lang==="ru") return "Покажи фотографии "+title+" и расскажи, для какого вечера эта зона подходит лучше всего. Если подходит — предложи следующий шаг к бронированию.";
  if(lang==="vi") return "Hãy cho tôi xem hình ảnh "+title+" và giải thích không gian này phù hợp nhất với kiểu buổi tối nào. Nếu phù hợp, hãy đề xuất bước tiếp theo để đặt bàn.";
  return "Show me photos of "+title+" and explain what kind of evening this space fits best. If it fits, suggest the next step toward a reservation.";
}

async function runConcierge(message){
  const clean=String(message||"").trim();
  if(!clean || store.get().conciergeBusy) return;
  const before=store.get();
  const historyBefore=before.conciergeHistory.slice(-8);
  store.set({
    conciergeBusy:true,
    conciergeHistory:[...before.conciergeHistory,{role:"user",content:clean}],
    conciergePlan:null,
    conciergeSpaceIds:[],
    conciergeNextAction:null
  });
  try{
    const state=store.get();
    const result=await askConcierge({
      message:clean,
      lang:state.lang,
      history:historyBefore,
      context:{
        selectedArea:state.selectedAreaId,
        visibleSpace:state.spaceDetailId,
        selectedMenuItemIds:state.selectedMenuIds,
        details:state.reservationDraft,
        guest:{name:state.reservationDraft.name||""}
      }
    });
    const current=store.get();
    store.set({
      conciergeBusy:false,
      conciergePlan:result.plan||null,
      conciergeSpaceIds:Array.isArray(result.spaceCardIds)?result.spaceCardIds:[],
      conciergeNextAction:result.nextAction||null,
      conciergeHistory:[...current.conciergeHistory,{role:"assistant",content:result.reply||""}]
    });
  }catch(error){
    console.error("Concierge request failed",error);
    const current=store.get();
    store.set({
      conciergeBusy:false,
      conciergeHistory:[...current.conciergeHistory,{role:"assistant",content:translate(current.lang,"concierge.error")}]
    });
  }
}

document.addEventListener("click",event=>{
  const target=event.target.closest("[data-action]");
  if(!target) return;
  const action=target.dataset.action;
  const state=store.get();

  if(action==="tab"){ event.preventDefault(); navigate(target.dataset.tab); return; }
  if(action==="lang"){ store.set({lang:target.dataset.lang}); return; }
  if(action==="category"){ store.set({category:target.dataset.category}); return; }

  if(action==="view-space"){
    const returnTab=state.tab==="space"?(state.spaceReturnTab||"home"):state.tab;
    store.set({tab:"space",spaceDetailId:target.dataset.id,spaceReturnTab:returnTab});
    return;
  }
  if(action==="space-back"){
    const next=state.spaceReturnTab||"home";
    if(ROUTABLE_TABS.has(next)) navigate(next);
    else store.set({tab:next});
    return;
  }
  if(action==="reserve-space"){ store.set({selectedAreaId:target.dataset.id,tab:"reserve",reservationStep:ReservationStep.DETAILS}); return; }
  if(action==="ask-space"){
    const space=discoverySpaceById(target.dataset.id);
    if(!space) return;
    navigate("concierge");
    store.set({conciergeSpaceIds:[space.id]});
    queueMicrotask(()=>runConcierge(promptForSpace(space,store.get().lang)));
    return;
  }
  if(action==="space-add-menu"){
    const id=target.dataset.id;
    if(!MENU_ITEMS.some(item=>item.id===id)) return;
    if(!state.selectedMenuIds.includes(id)) store.set({selectedMenuIds:[...state.selectedMenuIds,id]});
    return;
  }

  if(action==="event-request"){ store.set({tab:"reserve",reservationStep:ReservationStep.DETAILS,reservationDraft:{...state.reservationDraft,occasion:"Private Dining & Events"}}); return; }
  if(action==="toggle-menu-item"){
    const id=target.dataset.id;
    const selected=state.selectedMenuIds.includes(id);
    store.set({selectedMenuIds:selected?state.selectedMenuIds.filter(x=>x!==id):[...state.selectedMenuIds,id]});
    return;
  }
  if(action==="select-reserve-space"){ store.set({selectedAreaId:target.dataset.id,reservationErrors:{}}); return; }
  if(action==="reserve-next-details"){
    updateDraftFromDom();
    const next=store.get();
    const errors=validateDetails(next.reservationDraft);
    if(Object.keys(errors).length){ store.set({reservationErrors:errors}); return; }
    store.set({reservationErrors:{},reservationStep:ReservationStep.SPACE});
    return;
  }
  if(action==="reserve-next-space"){
    if(!canContinueFromSpace(state)){ store.set({reservationErrors:{space:"required"}}); return; }
    store.set({reservationErrors:{},reservationStep:ReservationStep.REVIEW});
    return;
  }
  if(action==="reserve-next-review"){ store.set({reservationStep:ReservationStep.DEPOSIT}); return; }
  if(action==="reserve-back"){ store.set({reservationStep:Math.max(ReservationStep.DETAILS,state.reservationStep-1),reservationErrors:{}}); return; }
  if(action==="reserve-confirm"){
    const request=createReservationRequest(state);
    store.set({reservationRequests:[request,...state.reservationRequests],reservationStep:ReservationStep.CONFIRMED});
    return;
  }

  if(action==="concierge-prompt"){ runConcierge(target.dataset.prompt); return; }
  if(action==="concierge-send"){
    const input=qs("#concierge-input");
    if(input){const value=input.value;input.value="";runConcierge(value);}
    return;
  }
  if(action==="concierge-reserve"){ store.update(current=>applyConciergePlan(current,current.conciergePlan)); return; }
  if(action==="concierge-add"){
    const ids=(state.conciergePlan?.menuItemIds||[]).filter(id=>MENU_ITEMS.some(item=>item.id===id));
    store.set({selectedMenuIds:[...new Set([...state.selectedMenuIds,...ids])],tab:"menu"});
    return;
  }
});

document.addEventListener("keydown",event=>{
  if(event.key==="Enter" && event.target?.id==="concierge-input"){
    event.preventDefault();
    const value=event.target.value;
    event.target.value="";
    runConcierge(value);
  }
});

window.addEventListener("hashchange",()=>{
  const tab=tabFromHash();
  if(store.get().tab!==tab) store.set({tab});
});

store.subscribe(render);
const missing=validateLocales();
if(missing.length) console.warn("Missing locale keys",missing);
const initialTab=tabFromHash();
if(store.get().tab!==initialTab) store.set({tab:initialTab});
if(!location.hash) navigate(initialTab,{replace:true});
else render();

