export const ReservationStep = Object.freeze({
  DETAILS:0,
  SPACE:1,
  REVIEW:2,
  DEPOSIT:3,
  CONFIRMED:4
});

export function validateDetails(draft){
  const errors={};
  if(!draft.name?.trim()) errors.name="required";
  if(!draft.phone?.trim()) errors.phone="required";
  if(!draft.date) errors.date="required";
  return errors;
}

export function canContinueFromSpace(state){
  return Boolean(state.selectedAreaId);
}

export function createReservationRequest(state){
  return Object.freeze({
    id:"LUME-"+Math.floor(10000+Math.random()*90000),
    createdAt:new Date().toISOString(),
    status:"request_created",
    areaId:state.selectedAreaId,
    menuItemIds:[...state.selectedMenuIds],
    details:{...state.reservationDraft}
  });
}

export function applyConciergePlan(state,plan){
  if(!plan) return state;
  const draft={...state.reservationDraft};
  if(plan.time) draft.time=plan.time;
  if(plan.guests) draft.guests=plan.guests;
  return {
    ...state,
    selectedAreaId:plan.areaId || state.selectedAreaId,
    selectedMenuIds:[...new Set([...state.selectedMenuIds,...(plan.menuItemIds||[])])],
    reservationDraft:draft,
    reservationStep:ReservationStep.DETAILS,
    tab:"reserve"
  };
}

