import en from "./locales/en.js";
import ru from "./locales/ru.js";
import vi from "./locales/vi.js";

const locales={en,ru,vi};
export const SUPPORTED_LANGS=Object.keys(locales);
export const DEFAULT_LANG="en";

export function t(lang,path){
  const source=locales[SUPPORTED_LANGS.includes(lang)?lang:DEFAULT_LANG]||en;
  return path.split(".").reduce((value,key)=>value?.[key],source) ?? path;
}
export function tr(lang,value){return value?.[lang]??value?.[DEFAULT_LANG]??"";}

function flatten(obj,prefix="",out=new Set()){
  Object.entries(obj).forEach(([key,value])=>{
    const path=prefix?prefix+"."+key:key;
    if(value&&typeof value==="object"&&!Array.isArray(value)) flatten(value,path,out);
    else out.add(path);
  });
  return out;
}
export function validateLocales(){
  const base=flatten(en),missing=[];
  for(const lang of SUPPORTED_LANGS){
    for(const path of base){
      const source=locales[lang];
      const value=path.split(".").reduce((v,k)=>v?.[k],source);
      if(value===undefined) missing.push(lang+":"+path);
    }
  }
  return missing;
}

